using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Topstar.Application.Disputes;
namespace Topstar.Web.Pages.Admin;[Authorize(Roles="Admin")]public sealed class DisputeDetailModel(IDisputeService service):PageModel{[BindProperty(SupportsGet=true)]public Guid Id{get;set;}public DisputeCaseDetail? Detail{get;private set;}[TempData]public string? Message{get;set;}[TempData]public bool MessageSuccess{get;set;}public async Task<IActionResult> OnGetAsync(CancellationToken ct){Detail=await service.GetDetailAsync(UserId(),"ADMIN",Id,ct);return Detail is null?NotFound():Page();}public async Task<IActionResult> OnPostMessageAsync(string body,string? evidenceUrl,bool adminOnly,CancellationToken ct){return Done(await service.AddMessageAsync(UserId(),"ADMIN",Id,body,evidenceUrl,adminOnly,ct));}public async Task<IActionResult> OnPostCancelCampaignAsync(string reason,CancellationToken ct){return Done(await service.CancelCampaignAsync(UserId(),Id,reason,ct));}public async Task<IActionResult> OnPostReleaseEarningsAsync(string reason,CancellationToken ct){return Done(await service.ReleaseEarningsAsync(UserId(),Id,reason,ct));}private IActionResult Done(DisputeResult x){Message=x.Message;MessageSuccess=x.Success;return RedirectToPage(new{id=Id});}private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);}
